     *
     * @see       useQuery()
     *
     * @param     string $relationAlias optional alias for the relation,
     *                                   to be used as main alias in the secondary query
     * @param     string $joinType Accepted values are null, 'left join', 'right join', 'inner join'
     *
     * @return   ClienteQuery A secondary query class using the current class as primary query
     */
    public function useClienteQuery($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        return $this
            ->joinCliente($relationAlias, $joinType)
            ->useQuery($relationAlias ? $relationAlias : 'Cliente', 'ClienteQuery');
    }

    /**
     * Exclude object from result
     *
     * @param   ClUsuario $clUsuario Object to remove from the list of results
     *
     * @return ClUsuarioQuery The current query, for fluid interface
     */
    public function prune($clUsuario = null)
    {
        if ($clUsuario) {
            $this->addUsingAlias(ClUsuarioPeer::CL_USUARIO_ID, $clUsuario->getClUsuarioId(), Criteria::NOT_EQUAL);
        }

        return $this;
    }

}
